create extension if not exists pgcrypto;
create table if not exists players (id uuid primary key default gen_random_uuid(), anonymous_id text unique not null, display_name text default 'Wanderer', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists worlds (id uuid primary key default gen_random_uuid(), player_id uuid references players(id), name text not null default 'First Expedition', seed text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists player_state (id uuid primary key default gen_random_uuid(), player_id uuid references players(id), world_id uuid references worlds(id), current_q integer not null default 0, current_r integer not null default 0, hp integer not null default 30, max_hp integer not null default 30, xp integer not null default 0, level integer not null default 1, gold integer not null default 0, shards integer not null default 0, inventory jsonb not null default '[]'::jsonb, flags jsonb not null default '{}'::jsonb, updated_at timestamptz default now());
create table if not exists hexes (id uuid primary key default gen_random_uuid(), world_id uuid references worlds(id), q integer not null, r integer not null, terrain text not null, explored boolean not null default false, visible boolean not null default false, encounter_id text, encounter_completed boolean not null default false, danger integer not null default 1, data jsonb not null default '{}'::jsonb, created_at timestamptz default now(), updated_at timestamptz default now(), unique(world_id,q,r));
create table if not exists world_events (id uuid primary key default gen_random_uuid(), world_id uuid references worlds(id), player_id uuid references players(id), hex_q integer, hex_r integer, event_type text not null, title text not null, description text not null, choice_made text, outcome jsonb not null default '{}'::jsonb, ai_text text, created_at timestamptz default now());
create table if not exists discovered_facts (id uuid primary key default gen_random_uuid(), world_id uuid references worlds(id), player_id uuid references players(id), fact_type text not null, title text not null, body text not null, source_event_id uuid references world_events(id), created_at timestamptz default now());
create table if not exists game_assets (id uuid primary key default gen_random_uuid(), asset_key text unique not null, asset_type text not null, terrain_type text, storage_path text not null, public_url text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz default now());
